function DemoToolbar({ mode, setMode, reset, openGuide }: { mode: DemoMode; setMode: (m: DemoMode) => void; reset: () => void; openGuide: () => void }) {
  const [mobileOpen, setMobileOpen] = useState(false);
  const labels: Record<DemoMode, string> = { marketing: "Website", lender: "Lender portal", consumer: "Consumer portal", integrations: "Integrations" };
  const choose = (next: DemoMode) => { setMobileOpen(false); setMode(next); };
  return <header className={`demo-toolbar ${mobileOpen ? "mobile-open" : ""}`}><div className="demo-toolbar-inner"><div className="demo-title"><BrandMark inverse /><span className="demo-divider" /><span>Live product tour</span></div><button className="demo-mobile-toggle" onClick={() => setMobileOpen(!mobileOpen)} aria-expanded={mobileOpen}><span><i />{labels[mode]}</span><b>{mobileOpen ? "Close" : "Switch"}</b></button><nav className="mode-switch" aria-label="Preview mode"><button className={mode === "marketing" ? "active" : ""} onClick={() => { setMobileOpen(false); if ((window as any).__ROUTE__ === "demo") { location.href = document.baseURI; } else setMode("marketing"); }}><span className="mode-dot marketing-dot" />Website</button><button className={mode === "lender" ? "active" : ""} onClick={() => choose("lender")}><span className="mode-dot lender-dot" />Lender portal</button><button className={mode === "consumer" ? "active" : ""} onClick={() => choose("consumer")}><span className="mode-dot consumer-dot" />Consumer portal</button><button className={mode === "integrations" ? "active" : ""} onClick={() => choose("integrations")}><span className="mode-dot integration-dot" />Integrations</button></nav><button className="guide-btn" onClick={openGuide}>✦ Guide</button><button className="reset-button" onClick={reset}>Reset tour ↻</button></div></header>;
}

