function ConsumerApp({ page, setPage, onExit, autoReview = 0 }: { page: ConsumerPage; setPage: (p: ConsumerPage) => void; onExit: () => void; autoReview?: number }) {
  const [review, setReview] = useState(false); const [guardian, setGuardian] = useState(false); const { es } = useLang(); useEffect(() => { if (autoReview) setReview(true); }, [autoReview]); if (page === "consent") return <div className="consumer-app"><ConsumerTopbar setPage={setPage} /><ConsentFlow onBack={onExit} onComplete={() => setPage("result")} /></div>;
  return <div className="consumer-app"><ConsumerTopbar setPage={setPage} /><div className="consumer-body"><ConsumerSidebar page={page} setPage={setPage} /><main className="consumer-content">{page === "result" && <Overview setPage={setPage} openReview={() => setReview(true)} />}{page === "plan" && <ActionPlan setPage={setPage} />}{(page === "disputes" || page === "reporting") && <Segments page={page} setPage={setPage} items={[["disputes", es ? "Disputas" : "Dispute Hub", es ? "2 marcados · 1 borrador" : "2 flagged · 1 draft"], ["reporting", es ? "Construir y reportar" : "Build & report", es ? "3 coincidencias" : "3 eligible matches"]]} />}{page === "disputes" && <DisputeHub />}{page === "reporting" && <PositiveReporting />}{page === "progress" && <ProgressPage openReview={() => setReview(true)} />}{(page === "passport" || page === "guardian") && <Segments page={page} setPage={setPage} items={[["passport", es ? "Pasaporte" : "Passport", es ? "lo que otros pueden ver" : "what others can see"], ["guardian", es ? "Modo Protección" : "Protect Mode", guardian ? (es ? "activo" : "on · loan in process") : (es ? "cuando empiece tu préstamo" : "on when your loan starts")]]} />}{page === "guardian" && <GuardianPage on={guardian} setOn={setGuardian} />}{page === "passport" && <PassportPage openReview={() => setReview(true)} />}</main></div><AskFab />{review && <ReviewPacket close={() => setReview(false)} />}</div>;
}

