export default function Home() {
  const __q = typeof location !== "undefined" ? new URLSearchParams(location.search) : new URLSearchParams(); const [mode, setMode] = useState<DemoMode>((__q.get("mode") as DemoMode) || ((window as any).__ROUTE__ === "demo" && !__q.get("c") && !__q.get("passport") ? "consumer" : "marketing")); const [consumerPage, setConsumerPage] = useState<ConsumerPage>((__q.get("cpage") as ConsumerPage) || "welcome"); const [lenderPage, setLenderPage] = useState<LenderPage>((__q.get("lpage") as LenderPage) || "link"); const [door, setDoor] = useState<string>(__q.get("c") || (__q.get("mode") === "consumer" ? "invite" : "public")); const __c0 = __q.get("c"); useEffect(() => { if (__c0 && !__q.get("mode")) { setConsumerPage("welcome"); setMode("consumer"); } }, []);
  const openDoor = (code: string) => { setDoor(code); setConsumerPage("welcome"); setMode("consumer"); };
  const [lang, setLang] = useState<Lang>((__q.get("lang") as Lang) === "es" ? "es" : "en"); const [guide, setGuide] = useState(__q.get("guide") === "1"); const [reviewTick, setReviewTick] = useState(0); const [pubPassport, setPubPassport] = useState<boolean>(!!__q.get("passport"));
  const go: Go = (m, page, extra) => { if (m === "consumer" && page) setConsumerPage(page as ConsumerPage); if (m === "consumer" && extra === "review") setReviewTick((t) => t + 1); if (m === "lender" && page) setLenderPage(page as LenderPage); setPubPassport(false); setMode(m); };
  useEffect(() => { if (window.location.hash) window.history.replaceState(null, "", window.location.pathname); window.scrollTo({ top: 0, behavior: "auto" }); }, [mode, consumerPage, lenderPage]);
  const reset = () => { setMode("marketing"); setConsumerPage("welcome"); setLenderPage("link"); setDoor("public"); };
  const view = useMemo(() => mode === "marketing" ? <ReadyIQWebsite openOrganization={() => setMode("lender")} openStart={() => { setLenderPage("start"); setMode("lender"); }} openConsumer={(page = "welcome") => { if (page === "welcome") setDoor("invite"); setConsumerPage(page); setMode("consumer"); }} openIntegrations={() => setMode("integrations")} /> : mode === "integrations" ? <IntegrationHub setMode={setMode} /> : mode === "lender" ? <LenderApp page={lenderPage} setPage={setLenderPage} setMode={setMode} openDoor={openDoor} /> : (consumerPage === "welcome" || consumerPage === "consent") ? <div className="door-page"><LenderWebsite door={resolveLink(door, lang)} onStart={() => document.getElementById("start")?.scrollIntoView({ behavior: "smooth", block: "start" })} /><EnrollSections autoScroll={consumerPage === "consent"} onComplete={() => setConsumerPage("result")} /></div> : <ConsumerApp page={consumerPage} setPage={setConsumerPage} onExit={() => setConsumerPage("welcome")} autoReview={reviewTick} />, [mode, consumerPage, lenderPage, door, lang, reviewTick]);
  return <LangContext.Provider value={{ lang, setLang }}><main><DemoToolbar mode={mode} setMode={setMode} reset={reset} openGuide={() => setGuide(true)} /><div className="demo-canvas">{pubPassport ? <PassportPublic getOwn={() => { setPubPassport(false); setDoor("public"); setConsumerPage("welcome"); setMode("consumer"); }} /> : view}</div><GuidePanel open={guide} close={() => setGuide(false)} go={go} /></main></LangContext.Provider>;
}
